/**
 * @file create-student-charge-item.dto.ts
 * @description One one-off member charge generated by another service (license batch).
 */

import { ApiProperty } from '@nestjs/swagger';
import { Transform } from 'class-transformer';
import { IsDateString, IsNotEmpty, IsString, IsUUID, Matches } from 'class-validator';

const MONEY_PATTERN = /^\d{1,8}(\.\d{1,2})?$/;

/**
 * Trims string monetary amounts so `Prisma.Decimal` receives a clean catalog value.
 *
 * @param {unknown} value - Raw body value.
 * @returns {unknown} Trimmed string, or the original value.
 */
function trimString(value: unknown): unknown {
  return typeof value === 'string' ? value.trim() : value;
}

/**
 * One fee row accepted by `POST /internal/financial/fees/batch`.
 * Amounts are Decimal strings — never JavaScript floats.
 */
export class CreateStudentChargeItemDto {
  @ApiProperty({ format: 'uuid', description: 'Auth-service payer (adult student or guardian).' })
  @IsUUID()
  payerUserId: string;

  @ApiProperty({ format: 'uuid', description: 'Academic StudentProfile id (logical, no FK).' })
  @IsUUID()
  studentProfileId: string;

  @ApiProperty({ example: '40.00', description: 'Charge amount as a Decimal string.' })
  @Transform(({ value }) => trimString(value))
  @Matches(MONEY_PATTERN, { message: 'INVALID_MONETARY_AMOUNT' })
  amount: string;

  @ApiProperty({ example: 'Affiliation license Standard 2026-2027' })
  @IsString()
  @IsNotEmpty()
  concept: string;

  @ApiProperty({ example: '2026-2027' })
  @IsString()
  @IsNotEmpty()
  seasonName: string;

  @ApiProperty({ example: '2027-08-31T00:00:00.000Z' })
  @IsDateString()
  dueDate: string;
}
